#!/bin/bash
set -euo pipefail
RUN=/var/lib/kalshi-study/reproduction-btc-20261117
SCRATCH=/mnt/scratch/reproduction
mkdir -p "$RUN" "$SCRATCH/panels/rich_BTC" "$SCRATCH/cache"
exec >>"$RUN/run.log" 2>&1
trap 'rc=$?; echo "FAIL $rc $(date -u --iso-8601=seconds)" | tee "$RUN/status.txt"' ERR
echo "RUNNING panel_rebuild $(date -u --iso-8601=seconds)" | tee "$RUN/status.txt"
printf '%s' '' | base64 -d > "$RUN/reproduce_tc.py"
cp -n "$SCRATCH"/smoke/panel_KXBTC15M-*.parquet "$SCRATCH/panels/rich_BTC/" || true
export PYTHONPATH=/opt/kalshi KALSHI_BLOB_ACCOUNT=kalshiobfdfaed53 KALSHI_BLOB_CONTAINER=tape KALSHI_CACHE="$SCRATCH/cache" SCALE_FREE_STRICT=1 PYTHONWARNINGS=ignore
/opt/kalshi/venv/bin/python -u -m tools.panel_parallel --coin BTC --dates 2026-09-15 2026-09-16 2026-09-17 2026-09-18 2026-09-19 2026-09-20 2026-09-21 2026-09-22 2026-09-23 2026-09-24 2026-09-25 2026-09-26 2026-09-27 2026-09-28 --tier rich --perp-book --every 25 --workers 12 --out "$SCRATCH/panels/rich_BTC" --resume

echo "RUNNING verify_inputs $(date -u --iso-8601=seconds)" | tee "$RUN/status.txt"
/opt/kalshi/venv/bin/python - <<'PYCODE'
import os,glob,json,hashlib,platform
import pandas as pd,pyarrow.parquet as pq,torch
from tools.panel_model import scale_free
root='/mnt/scratch/reproduction/panels/rich_BTC'; paths=sorted(glob.glob(root+'/panel_KXBTC15M-*.parquet'))
valid=[p for p in paths if os.path.exists('/var/lib/kalshi-study/midtape/mid_'+os.path.basename(p)[6:])]
if len(valid)<1000: raise RuntimeError(f'Only {len(valid)} panels have matching midpoint tape; refusing an unrepresentative reproduction')
probe=paths[::max(1,len(paths)//12)][:12]; feats=set()
for p in probe:
 d=pd.read_parquet(p); s=scale_free(d[[c for c in d if c.startswith(('k_','p_','y_','ry_')) or c=='market']]);feats.update(c for c in s if not c.startswith(('y_','ry_','market','_day')))
if len(feats)!=219:raise RuntimeError(f'Feature count {len(feats)} != expected 219; refusing mismatched run')
def digest(p):
 h=hashlib.sha256()
 with open(p,'rb') as f:
  for b in iter(lambda:f.read(4*1024*1024),b''):h.update(b)
 return h.hexdigest()
files=[{'name':os.path.basename(p),'bytes':os.path.getsize(p),'rows':pq.ParquetFile(p).metadata.num_rows,'sha256':digest(p)} for p in paths]
out={'panels':len(paths),'panels_with_mid_tape':len(valid),'expected_original_test_markets':351,'rebuilt_test_markets':int(.3*len(valid)),'features':sorted(feats),'panel_files':files,'python':platform.python_version(),'torch':torch.__version__,'pandas':pd.__version__,'source_hashes':{p:digest(p) for p in ['/var/lib/kalshi-study/scripts/tc.py','/opt/kalshi/tools/panel_parallel.py','/opt/kalshi/tools/panel_model.py']}}
json.dump(out,open('/var/lib/kalshi-study/reproduction-btc-20261117/input_manifest.json','w'),indent=2)
print('VERIFIED panels',len(paths),'with_mids',len(valid),'features',len(feats),'test_markets',int(.3*len(valid)),flush=True)
PYCODE

echo "RUNNING train_and_evaluate $(date -u --iso-8601=seconds)" | tee "$RUN/status.txt"
export TC_COINS=BTC TC_THREADS=12 REPRO_PANELS="$SCRATCH/panels" REPRO_OUTPUT_DIR="$RUN/output"
/opt/kalshi/venv/bin/python -u "$RUN/reproduce_tc.py"
echo "RUNNING upload $(date -u --iso-8601=seconds)" | tee "$RUN/status.txt"
# Save immutable reproduction outputs to a new blob for retrieval to the user's workspace.
tar -C "$RUN" -czf "$RUN/artifacts.tgz" reproduce_tc.py input_manifest.json output run.log
/opt/kalshi/venv/bin/python - <<'PYCODE'
from azure.identity import DefaultAzureCredential
from azure.storage.blob import BlobServiceClient
path='/var/lib/kalshi-study/reproduction-btc-20261117/artifacts.tgz'
blob=BlobServiceClient('https://kalshiobfdfaed53.blob.core.windows.net',credential=DefaultAzureCredential()).get_blob_client('tape','research/reproductions/btc-tradecheck-20261117/artifacts.tgz')
with open(path,'rb') as f:blob.upload_blob(f,overwrite=False)
print('Uploaded reproduction artifact',flush=True)
PYCODE
echo "COMPLETE $(date -u --iso-8601=seconds)" | tee "$RUN/status.txt"
